        expect(
          stub['version'],
          entry.value,
          reason: 'stub version should mirror the impl it replaces so the '
              'umbrella constraint stays satisfied.',
        );
        expect(
          stub['publish_to'],
          'none',
          reason: 'stubs are repo-internal, never published.',
        );
