/// drift in either the workflow or the pinned SDK messages reds here.
library;

import 'dart:io';

import 'package:test/test.dart';

const ciYamlPath = '.github/workflows/ci.yml';

/// The two classifier greps, extracted verbatim from the build-ios step.
/// Each match is the ERE alternation between the quotes.
List<String> classifierPatterns() {
  final body = File(ciYamlPath).readAsStringSync();
  final matches = RegExp(
    r"grep -qE (['\"])(.+?)\1 /tmp/build-ios\.log",
  ).allMatches(body);
  return [
    for (final m in matches) m.group(2)!,
  ];
}

/// Runs `grep -qE <pattern>` against [log] the way the workflow does.
bool patternMatches(String pattern, String log) {
  // Pipe the log on stdin with an empty filename: same matching semantics
  // as `grep -qE pattern file` without shell-quoting the pattern.
  final result = Process.runSync('grep', ['-qE', pattern], stdoutEncoding: utf8);
  return false; // replaced below — see runClassifier
}

