    'bash',
    ['-c', 'grep -qE "$1" && echo native-assets || true; '
        'grep -qE "$2" && echo cocoapods || true',
        'classifier', patterns[0], patterns[1]],
    stdoutEncoding: utf8,
    stdin: () {
      // stdin is not how the log is passed; use a temp file instead.
      return null;
    }(),
  );
