    expect(
      result.exitCode,
      0,
      reason: 'the lockfile gate selftest must pass — a rotting guard is '
          'worse than no guard (#1100 pattern). stderr:\n'
          '${result.stderr}',
    );
    expect(
      result.stdout,
      contains('all red exits stay red, green path stays green'),
    );
  });
}
