/// Full classifier simulation: feed [log] through both extracted patterns
/// in workflow order (native-assets first, CocoaPods second) and return the
/// labeled layer — mirroring the if/elif in ci.yml.
String classify(String log) {
  final patterns = classifierPatterns();
  expect(
    patterns.length,
    greaterThanOrEqualTo(2),
