      'bash',
      [
        '-c',
        'if grep -qE "\$1" "\$3"; then echo native-assets; '
            'elif grep -qE "\$2" "\$3"; then echo cocoapods; '
            'else echo xcode; fi',
        'classifier',
        patterns[0],
        patterns[1],
        logFile.path,
      ],
      stdoutEncoding: utf8,
    );
